CREATE TABLE IF NOT EXISTS messes (mess_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, mess_name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS food_categories (category_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS foods (food_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, food_name VARCHAR(150) NOT NULL UNIQUE, category_id INTEGER REFERENCES food_categories(category_id), description TEXT, default_serving_g NUMERIC(8,2) CHECK (default_serving_g > 0), default_serving_desc VARCHAR(100));
CREATE TABLE IF NOT EXISTS menus (menu_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, mess_id INTEGER NOT NULL REFERENCES messes(mess_id) ON DELETE CASCADE, menu_date DATE NOT NULL, meal_type VARCHAR(20) NOT NULL CHECK (meal_type IN ('breakfast','lunch','snacks','dinner')), scraped_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(mess_id,menu_date,meal_type));
CREATE TABLE IF NOT EXISTS menu_items (menu_id BIGINT NOT NULL REFERENCES menus(menu_id) ON DELETE CASCADE, food_id BIGINT NOT NULL REFERENCES foods(food_id), serving_weight_g NUMERIC(8,2) CHECK (serving_weight_g > 0), serving_description VARCHAR(100), PRIMARY KEY(menu_id,food_id));
CREATE TABLE IF NOT EXISTS nutrition (nutrition_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, food_id BIGINT NOT NULL UNIQUE REFERENCES foods(food_id) ON DELETE CASCADE, basis_amount NUMERIC(8,2) NOT NULL DEFAULT 100 CHECK(basis_amount>0), basis_unit VARCHAR(10) NOT NULL DEFAULT 'g', calories_kcal NUMERIC(8,2) CHECK(calories_kcal>=0), protein_g NUMERIC(8,2) CHECK(protein_g>=0), carbs_g NUMERIC(8,2) CHECK(carbs_g>=0), fat_g NUMERIC(8,2) CHECK(fat_g>=0), fiber_g NUMERIC(8,2) CHECK(fiber_g>=0), sugar_g NUMERIC(8,2) CHECK(sugar_g>=0), source TEXT, confidence VARCHAR(10) CHECK(confidence IN ('low','medium','high')));
CREATE TABLE IF NOT EXISTS users (username VARCHAR(20) PRIMARY KEY CHECK(username NOT IN ('admin','administrator','root','support','system','flexi','flexiadmin')), name VARCHAR(100) NOT NULL CHECK (length(trim(name)) > 0), password_hash TEXT NOT NULL CHECK (length(password_hash) > 0), hostel_id INTEGER REFERENCES messes(mess_id) ON DELETE SET NULL, role VARCHAR(10) NOT NULL DEFAULT 'student' CHECK(role IN ('student','admin')), is_active BOOLEAN NOT NULL DEFAULT TRUE, failed_login_count INTEGER NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0), locked_until TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_login_at TIMESTAMPTZ);
-- Per-meal nutrient targets; limits match PREFERENCE_NUTRIENTS in app/models.py. Note the "fibre" spelling.
CREATE TABLE IF NOT EXISTS user_preferences (
  username VARCHAR(20) PRIMARY KEY REFERENCES users(username) ON UPDATE CASCADE ON DELETE CASCADE,
  breakfast_calories_kcal NUMERIC(6,0) CHECK (breakfast_calories_kcal BETWEEN 0 AND 2000),
  lunch_calories_kcal     NUMERIC(6,0) CHECK (lunch_calories_kcal BETWEEN 0 AND 2000),
  snacks_calories_kcal    NUMERIC(6,0) CHECK (snacks_calories_kcal BETWEEN 0 AND 2000),
  dinner_calories_kcal    NUMERIC(6,0) CHECK (dinner_calories_kcal BETWEEN 0 AND 2000),
  breakfast_protein_g NUMERIC(6,1) CHECK (breakfast_protein_g BETWEEN 0 AND 300),
  lunch_protein_g     NUMERIC(6,1) CHECK (lunch_protein_g BETWEEN 0 AND 300),
  snacks_protein_g    NUMERIC(6,1) CHECK (snacks_protein_g BETWEEN 0 AND 300),
  dinner_protein_g    NUMERIC(6,1) CHECK (dinner_protein_g BETWEEN 0 AND 300),
  breakfast_carbs_g NUMERIC(6,1) CHECK (breakfast_carbs_g BETWEEN 0 AND 300),
  lunch_carbs_g     NUMERIC(6,1) CHECK (lunch_carbs_g BETWEEN 0 AND 300),
  snacks_carbs_g    NUMERIC(6,1) CHECK (snacks_carbs_g BETWEEN 0 AND 300),
  dinner_carbs_g    NUMERIC(6,1) CHECK (dinner_carbs_g BETWEEN 0 AND 300),
  breakfast_fibre_g NUMERIC(6,1) CHECK (breakfast_fibre_g BETWEEN 0 AND 100),
  lunch_fibre_g     NUMERIC(6,1) CHECK (lunch_fibre_g BETWEEN 0 AND 100),
  snacks_fibre_g    NUMERIC(6,1) CHECK (snacks_fibre_g BETWEEN 0 AND 100),
  dinner_fibre_g    NUMERIC(6,1) CHECK (dinner_fibre_g BETWEEN 0 AND 100),
  breakfast_sugar_g NUMERIC(6,1) CHECK (breakfast_sugar_g BETWEEN 0 AND 300),
  lunch_sugar_g     NUMERIC(6,1) CHECK (lunch_sugar_g BETWEEN 0 AND 300),
  snacks_sugar_g    NUMERIC(6,1) CHECK (snacks_sugar_g BETWEEN 0 AND 300),
  dinner_sugar_g    NUMERIC(6,1) CHECK (dinner_sugar_g BETWEEN 0 AND 300),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS meal_logs (log_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(20) NOT NULL REFERENCES users(username) ON UPDATE CASCADE ON DELETE CASCADE, log_date DATE NOT NULL, mess_id INTEGER NOT NULL REFERENCES messes(mess_id), meal_type VARCHAR(20) NOT NULL CHECK(meal_type IN ('breakfast','lunch','snacks','dinner')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(username,log_date,mess_id,meal_type));
-- Stores the food NAME (no FK to foods) plus a nutrition snapshot for the grams eaten.
CREATE TABLE IF NOT EXISTS meal_log_items (item_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, log_id BIGINT NOT NULL REFERENCES meal_logs(log_id) ON DELETE CASCADE, food_name VARCHAR(150) NOT NULL, grams NUMERIC(7,1) NOT NULL CHECK (grams > 0), calories_kcal NUMERIC(8,2), protein_g NUMERIC(8,2), carbs_g NUMERIC(8,2), fat_g NUMERIC(8,2), fiber_g NUMERIC(8,2), sugar_g NUMERIC(8,2), UNIQUE(log_id,food_name));
CREATE INDEX IF NOT EXISTS menus_date_meal_idx ON menus(menu_date,meal_type);
CREATE INDEX IF NOT EXISTS foods_name_idx ON foods(food_name);
CREATE INDEX IF NOT EXISTS meal_logs_user_date_idx ON meal_logs(username,log_date DESC);
-- Unique indexes also support the ON CONFLICT clauses used by the scraper.
CREATE UNIQUE INDEX IF NOT EXISTS messes_mess_name_uq ON messes(mess_name);
CREATE UNIQUE INDEX IF NOT EXISTS foods_food_name_uq ON foods(food_name);
